const { withAppBuildGradle } = require('expo/config-plugins');

/**
 * Drops the signed bundle into `play-assets/` as soon as it is built.
 *
 * The upload pack in `play-assets/` is what actually gets dragged into Play
 * Console, and until now the bundle got there by being copied across by hand
 * after every build. That is exactly the kind of step that gets skipped once,
 * quietly leaving a stale bundle in the folder that looks entirely current —
 * and uploading last week's build to production is not a mistake you notice
 * until someone reports a bug you already fixed.
 *
 * A config plugin rather than a hand edit for the same reason as
 * withAndroidUploadSigning: `expo prebuild` regenerates `android/` from
 * scratch, so anything written straight into app/build.gradle is gone the
 * next time the native config changes.
 *
 * The copy deletes the previous `TheraHOME-*.aab` first. That is the point:
 * the folder should hold exactly one bundle, the newest, so there is nothing
 * to pick wrongly from. It only ever removes files matching the name this
 * task itself writes, and it prints what it removed.
 */
const MARKER = '// >>> therahome: copy the signed bundle into play-assets';

const GRADLE_BLOCK = `
${MARKER}
// See plugins/withPlayAssetsBundleCopy.js — edit it there, not here; this
// file is regenerated by \`expo prebuild\`.
def playAssetsDir = file("\${rootProject.projectDir}/../../play-assets")

tasks.register("copyBundleToPlayAssets") {
    description = "Copies the signed release bundle into play-assets/ for Play Console."
    doLast {
        def bundle = file("\${project.buildDir}/outputs/bundle/release/app-release.aab")
        if (!bundle.exists()) {
            logger.lifecycle("play-assets: no bundle at \${bundle}, nothing copied")
            return
        }
        if (!playAssetsDir.exists()) {
            logger.lifecycle("play-assets: \${playAssetsDir} does not exist, nothing copied")
            return
        }
        def versionName = android.defaultConfig.versionName
        def versionCode = android.defaultConfig.versionCode
        def target = new File(playAssetsDir, "TheraHOME-\${versionName}-versionCode\${versionCode}.aab")

        playAssetsDir.listFiles({ f -> f.name.startsWith("TheraHOME-") && f.name.endsWith(".aab") } as FileFilter)?.each { old ->
            if (old.absolutePath != target.absolutePath && old.delete()) {
                logger.lifecycle("play-assets: removed stale \${old.name}")
            }
        }

        java.nio.file.Files.copy(
            bundle.toPath(),
            target.toPath(),
            java.nio.file.StandardCopyOption.REPLACE_EXISTING
        )
        logger.lifecycle("play-assets: \${target.name} updated")
    }
}

tasks.matching { it.name == "bundleRelease" }.configureEach {
    finalizedBy("copyBundleToPlayAssets")
}
// <<< therahome
`;

module.exports = function withPlayAssetsBundleCopy(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.contents.includes(MARKER)) return cfg;
    cfg.modResults.contents = `${cfg.modResults.contents.trimEnd()}\n${GRADLE_BLOCK}`;
    return cfg;
  });
};
